public class PropertyListBuilderTest {
    private ConfigurationProperties configurationProperties;
    private Map<String, Object> rootEntries;

    @Mock
    private PropertyListBuilder subject;

    @Before
    public void setup() throws Exception {
        configurationProperties = new ConfigurationProperties();
        rootEntries = new LinkedHashMap<>();
    }

    @Test
    public void test_add_property_gets_added_to_root_entries() {
        List<Property<?>> properties = List.of(new Property("property1"), new Property("property2"));
        when(configurationProperties.getRootEntries()).thenReturn(rootEntries);
        subject.add(properties.get(0));
        verify(rootEntries, times(1)).put("property1", "value1");
        verify(rootEntries, times(1)).put("property2", "value2");
    }

    @Test
    public void test_add_property_returns_empty_list_when_no_properties_added() {
        when(configurationProperties.getRootEntries()).thenReturn(null);
        List<Property<?>> properties = new ArrayList<>();
        subject.add(properties);
        verify(rootEntries, times(0)).put("property1", "value1");
        verify(rootEntries, times(0)).put("property2", "value2");
    }

    @Test
    public void test_get_root_entries_Returns_null_if_root_entries_are_none() {
        when(configurationProperties.getRootEntries()).thenReturn(null);
        subject.setup();
        assertEquals(null, subject.getRootEntries());
    }

    @Test
    public void test_get_root_entries_returns_map_with_empty_list_when_no_root_entries() {
        Map<String, Object> rootMap = new LinkedHashMap<>();
        configurationProperties.setRootEntries(rootMap);
        when(configurationProperties.getRootEntries()).thenReturn(rootMap);
        subject.setup();
        assertEquals(Map.of(), subject.getRootEntries());
    }

    @Test
    public void test_get_root_entries_returns_map_with_single_entry_when_single_property_added() {
        List<Property<?>> properties = new ArrayList<>();
        properties.add(new Property("property1"));
        when(configurationProperties.getRootEntries()).thenReturn(rootEntries);
        subject.setup();
        assertEquals(Map.of("property1", "value1"), subject.getRootEntries());
    }

    @Test
    public void test_get_root_entries_returns_empty_map_when_no_properties() {
        List<Property<?>> properties = new ArrayList<>();
        when(configurationProperties.getRootEntries()).thenReturn(null);
        subject.setup();
        assertEquals(Map.of(), subject.getRootEntries());
    }
}
